# scripts/populate_chunk3.py
import json

def parse_csv_block(raw_text):
    records = []
    lines = raw_text.strip().split("\n")
    for line in lines:
        line = line.strip()
        if not line or line.startswith("PROVINCIA"):
            continue
        parts = line.split(";")
        if len(parts) < 8:
            continue
        station = int(parts[2])
        mag = int(parts[3])
        year = int(parts[5])
        month = int(parts[6])
        values = []
        for i in range(1, 32):
            d_idx = 7 + (i - 1) * 2
            v_idx = d_idx + 1
            if d_idx < len(parts) and v_idx < len(parts):
                val_str = parts[d_idx].replace(",", ".")
                valid = parts[v_idx] == "V"
                try:
                    val = float(val_str)
                    if valid and val >= 0:
                        values.append(val)
                    else:
                        values.append(None)
                except:
                    values.append(None)
            else:
                values.append(None)
        records.append({
            "s": station,
            "m": mag,
            "y": year,
            "mo": month,
            "v": values
        })
    return records

